def sum_div(number):
    """Write a function to return the sum of all divisors of a number."""
    if number <= 1:
        return 0
    total = 1
    i = 2
    while i * i <= number:
        if number % i == 0:
            total += i
            other = number // i
            if other != i:
                total += other
        i += 1
    return total
